 fetched=j(HERE/'fetch-receipt.json');metadata=j(HERE/'metadata-receipt.json');base=j(ROOT/'.runs/licensed-closure-audit-003/audit.json');assert fetched['status']=='acquired_for_rights_inspection_only'
